import{_ as e,o,c as a,a2 as n}from"./chunks/framework.7R1OEGYz.js";const c=JSON.parse('{"title":"Auto approve","description":"","frontmatter":{},"headers":[],"relativePath":"auto-approve.md","filePath":"auto-approve.md","lastUpdated":null}'),r={name:"auto-approve.md"};function s(i,t,l,p,h,d){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="auto-approve" tabindex="-1">Auto approve <a class="header-anchor" href="#auto-approve" aria-label="Permalink to &quot;Auto approve&quot;">​</a></h1><p>Normally every tool a session wants to use raises a permission prompt — in the web app, and in your messenger if you set one up. <strong>Auto approve</strong> answers those prompts with &quot;allow&quot; automatically, so the agent works without stopping to ask.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p><strong>For a new session</strong> — tick <em>Auto approve</em> in the new-session dialog.</p><p><strong>For a session that is already running</strong> — use the toggle in the bar above the terminal, or the checkbox in <em>Edit session</em>. It takes effect immediately, with no restart: the backend evaluates the flag on every permission request rather than baking it into the pod.</p><p>Switching it on also clears the prompts that are already waiting. Without that they would keep the agent blocked for the rest of its poll window, because auto approve only short-circuits <em>new</em> requests.</p><p>You can turn it off again at any time; the next request prompts as usual.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Recommended for <strong>non-root containers</strong>.</p><p>With <em>Run as root</em>, the agent may run any command as root inside that container, unattended — combine the two only for a container you would have handed over anyway. The UI warns when both are on.</p><p>What does not change: the session&#39;s own container is still the boundary. Network policies, the unprivileged pod spec, and the per-user secret mounts all still apply, so the blast radius stays that one container. Auto approve grants nothing outside it.</p><p>A reasonable rule of thumb:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Auto approve</th></tr></thead><tbody><tr><td>Throwaway container, scratch repo</td><td>Fine</td></tr><tr><td>Long-running session on a repo you care about</td><td>Prefer <em>Allow (don&#39;t ask again)</em> per tool</td></tr><tr><td><code>Run as root</code> enabled</td><td>Only if you would hand the container over anyway</td></tr><tr><td>Session reachable by a linked Telegram group</td><td>Remember everyone in that group could have approved anyway</td></tr></tbody></table><h2 id="related-allow-always" tabindex="-1">Related: allow always <a class="header-anchor" href="#related-allow-always" aria-label="Permalink to &quot;Related: allow always&quot;">​</a></h2><p>The per-prompt <strong>Allow (don&#39;t ask again)</strong> button is the narrower tool. It whitelists that one tool for the rest of the session and keeps prompting for everything else. If you find yourself approving the same two tools over and over, that is usually the better answer than auto approve.</p>',15)])])}const m=e(r,[["render",s]]);export{c as __pageData,m as default};
